<?php
declare(strict_types=1);
require dirname(__DIR__).'/src/bootstrap.php';
use Asyura\Security;
$publicId=(string)($_GET['site']??'');$stmt=$db->prepare('SELECT * FROM sites WHERE public_id=? AND active=1 LIMIT 1');$stmt->execute([$publicId]);$site=$stmt->fetch();if(!$site){http_response_code(404);exit('ページが見つかりません。');}$q=$db->prepare('SELECT * FROM notices WHERE (site_id IS NULL OR site_id=?) AND is_public=1 AND (starts_at IS NULL OR starts_at<=NOW()) AND (ends_at IS NULL OR ends_at>=NOW()) ORDER BY is_pinned DESC,created_at DESC');$q->execute([$site['id']]);$notices=$q->fetchAll();$canonical=app_url('public/notices.php?site='.rawurlencode($site['public_id']));header('X-Content-Type-Options: nosniff');header('Content-Security-Policy: default-src \'self\'; style-src \'self\' \'unsafe-inline\'; img-src https: data:; base-uri \'none\'');
?><!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>お知らせ | <?=e($site['name'])?></title><meta name="description" content="<?=e($site['name'])?>からのお知らせです。"><link rel="canonical" href="<?=e($canonical)?>"><style>body{margin:0;background:#f6f7f7;color:#1d2327;font:15px/1.7 -apple-system,BlinkMacSystemFont,"Segoe UI","Noto Sans JP",sans-serif}.wrap{max-width:900px;margin:30px auto;padding:0 16px}article{background:#fff;border:1px solid #dcdcde;padding:18px;margin:0 0 14px}time{color:#646970}h1{font-size:28px}h2{font-size:20px;margin:.3em 0}</style></head><body><main class="wrap"><h1>お知らせ</h1><?php foreach($notices as $n):?><article><time datetime="<?=e($n['created_at'])?>"><?=e(substr($n['created_at'],0,10))?></time><h2><?=e($n['title'])?></h2><p><?=nl2br(e($n['body']))?></p></article><?php endforeach?><?php if(!$notices):?><p>現在、お知らせはありません。</p><?php endif?></main></body></html>
